  const m4=new THREE.Matrix4(),q=new THREE.Quaternion(),pp=new THREE.Vector3(),sc=new THREE.Vector3(1,1,1);let k=0;
  for(const a of lightAng){q.setFromAxisAngle(new THREE.Vector3(1,0,0),-a);for(let i=0;i<perRow;i++){pp.set(-HL/2+4+i*3.4+1.7,YC+(RH-1.3)*Math.cos(a),(RH-1.3)*Math.sin(a));m4.compose(pp,q,sc);lm.setMatrixAt(k++,m4);}}
  scene.add(lm);
