function buildStairwell(){
  const D=2.6,W=2.2,Lh=2.55,g=new THREE.Group();g.position.set(STAIR.cx,FLOOR_Y,STAIR.cz);g.rotation.y=STAIR.rot;scene.add(g);
  const white=mat(0xf1f1ee),grey=mat(0xd2d2cd),dark=new THREE.MeshBasicMaterial({color:0x1a1a1a});
  // walls
  for(const sx of [-1,1]){const w=new THREE.Mesh(new THREE.BoxGeometry(0.12,D,2*Lh),white);w.position.set(sx*(W/2+0.06),-D/2,0);g.add(w);}
  for(const sz of [-1,1]){const w=new THREE.Mesh(new THREE.BoxGeometry(W+0.24,D,0.12),white);w.position.set(0,-D/2,sz*(Lh+0.06));g.add(w);}
  // steps from the infield end (z+) down towards the track, then landing and tunnel under the track
  const N=12,run=3.4/N;
  for(let i=0;i<N;i++){const top=-(i+1)*D/N,z1=Lh-i*run;const st=new THREE.Mesh(new THREE.BoxGeometry(W,D+top+0.001,run),i%2?grey:white);st.position.set(0,(-D+top)/2,z1-run/2);g.add(st);
    const nose=new THREE.Mesh(new THREE.BoxGeometry(W,0.02,0.04),mat(0x888888));nose.position.set(0,top+0.01,z1-run+0.02);g.add(nose);}
  const fl=new THREE.Mesh(new THREE.BoxGeometry(W,0.05,2*Lh-3.4),grey);fl.position.set(0,-D,-Lh+(2*Lh-3.4)/2);g.add(fl);
  const tun=new THREE.Mesh(new THREE.PlaneGeometry(1.0,2.2),dark);tun.rotation.y=-PI/2;tun.position.set(W/2-0.005,-D+1.1,-Lh+0.6);g.add(tun);
  const lamp=new THREE.Mesh(new THREE.BoxGeometry(0.8,0.05,0.12),new THREE.MeshBasicMaterial({color:0xffffff}));lamp.position.set(W/2-0.2,-0.35,-Lh+0.6);g.add(lamp);
  // railing around the opening (entrance open on the infield side) + handrail down the stairs
  const rm=mat(0x9aa0a4);
  const rail=(ax,az,bx,bz)=>{for(const hy of [0.5,1.0]){const r=limb(rm,0.022);place(r,V(ax,hy,az),V(bx,hy,bz));g.add(r);}
    const L=Math.hypot(bx-ax,bz-az);for(let d=0;d<=L+1e-3;d+=1.0){const po=limb(rm,0.025);const x=ax+(bx-ax)*d/L,z=az+(bz-az)*d/L;place(po,V(x,0,z),V(x,1.02,z));g.add(po);}};
  const rx=W/2+0.12,rz=Lh+0.12;rail(-rx,-rz,rx,-rz);rail(-rx,-rz,-rx,rz);rail(rx,-rz,rx,rz);
  for(const sx of [-1,1]){const hr=limb(rm,0.02);place(hr,V(sx*(W/2-0.05),0.9,Lh),V(sx*(W/2-0.05),-D+0.9,Lh-3.4));g.add(hr);}
  const cap=(w,d,x,z)=>{const c=new THREE.Mesh(new THREE.BoxGeometry(w,0.08,d),white);c.position.set(x,0.03,z);g.add(c);};
  cap(0.3,2*Lh+0.3,-rx,0);cap(0.3,2*Lh+0.3,rx,0);cap(W+0.5,0.3,0,-rz);
}
